import org.junit.jupiter.api.Test;

/** Captures request-parameter and runtime-sibling entry contracts for prepared statement inputs. */
class InputOriginRouteDiagnosticTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:origin-route:subject");
	private static final IRI PREDICATE = VF.createIRI("urn:origin-route:predicate");

	@Test
	void comparesRawRequestRetainedRequestAndRuntimeSiblingRoutes() {
		Literal caller = VF.createLiteral("label", "EN");
		Literal stored = VF.createLiteral("label", "EN");
		Literal prepared = VF.createLiteral("label", "en");
		Statement statement = VF.createStatement(SUBJECT, PREDICATE, stored);
		TestSource source = new TestSource(caller, prepared, statement);
		BindingSet input = bindings("x", caller);
		Filter filter = filter();

		List<BindingSet> rawMappedInput = evaluate(source, filter.clone(), input);
		List<BindingSet> hiddenRequestWithoutOptimization = evaluate(source, filter.clone(),
				BindingSetOrigin.optimizationInput(input));
		TupleExpr optimized = optimize(source, filter.clone(), input);
		List<BindingSet> optimizedMappedInput = evaluate(source, optimized.clone(), input);
		List<BindingSet> optimizedHiddenRequest = evaluate(source, optimized,
				BindingSetOrigin.optimizationInput(input));

		BindingSetAssignment siblingValues = values(caller);
		TupleExpr runtimeSibling = new QueryRoot(new Join(siblingValues, filter()));
		List<BindingSet> siblingInput = evaluate(source, runtimeSibling, EmptyBindingSet.getInstance());

		System.out.println("input-origin routes"
				+ "\n  direct raw request mapping=" + rows(rawMappedInput, caller, stored, prepared)
				+ "\n  retained request without optimization="
				+ rows(hiddenRequestWithoutOptimization, caller, stored, prepared)
				+ "\n  optimized raw mapping=" + rows(optimizedMappedInput, caller, stored, prepared)
				+ "\n  optimized retained request=" + rows(optimizedHiddenRequest, caller, stored, prepared)
				+ "\n  runtime sibling mapping=" + rows(siblingInput, caller, stored, prepared));

		assertThat(rawMappedInput).isEmpty();
		assertThat(hiddenRequestWithoutOptimization).singleElement()
				.satisfies(row -> assertThat(row.getValue("x")).isSameAs(stored));
		assertThat(optimizedMappedInput).singleElement()
				.satisfies(row -> assertThat(row.getValue("x")).isSameAs(caller));
		assertThat(optimizedHiddenRequest).singleElement()
				.satisfies(row -> assertThat(row.getValue("x")).isSameAs(caller));
		assertThat(siblingInput).isEmpty();
	}

	private static List<BindingSet> evaluate(TestSource source, TupleExpr expression, BindingSet input) {
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(expression).evaluate(input)) {
			while (iteration.hasNext()) {
				rows.add(new QueryBindingSet(iteration.next()));
			}
		}
		return rows;
	}

	private static TupleExpr optimize(TestSource source, TupleExpr expression, BindingSet input) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		StandardQueryOptimizerPipeline delegate = new StandardQueryOptimizerPipeline(strategy, source,
				new EvaluationStatistics());
		strategy.setOptimizerPipeline(new QueryOptimizerPipeline() {
			@Override
			public Iterable<QueryOptimizer> getOptimizers() {
				return delegate.getOptimizers();
			}

			@Override
			public BindingSet getOptimizerInputBindings(QueryOptimizer optimizer, BindingSet initialBindings) {
				return delegate.getOptimizerInputBindings(optimizer, initialBindings);
			}
		});
		return strategy.optimize(new QueryRoot(expression), new EvaluationStatistics(), input);
	}

	private static Filter filter() {
		return new Filter(new StatementPattern(Var.of("s"), Var.of("p", PREDICATE), Var.of("x")),
				new Compare(new Lang(Var.of("x")), new ValueConstant(VF.createLiteral("EN"))));
	}

	private static BindingSetAssignment values(Value value) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of("x"));
		assignment.setBindingSets(List.of(new ListBindingSet(List.of("x"), value)));
		return assignment;
	}

	private static BindingSet bindings(String name, Value value) {
		MapBindingSet result = new MapBindingSet(1);
		result.addBinding(name, value);
		return result;
	}

	private static List<String> rows(List<BindingSet> rows, Value caller, Value stored, Value prepared) {
		return rows.stream().map(row -> "x=" + label(row.getValue("x"), caller, stored, prepared)).toList();
	}

	private static String label(Value value, Value caller, Value stored, Value prepared) {
		if (value == null) {
			return "null";
		}
		String identity = value == caller ? "caller" : value == stored ? "stored" : value == prepared ? "prepared"
				: "other";
		String language = value instanceof Literal literal ? literal.getLanguage().orElse("-") : "-";
		return identity + ':' + value + " lang=" + language;
	}

	private static final class TestSource implements TripleSource {
		private final Literal caller;
		private final Literal prepared;
		private final Statement statement;

		private TestSource(Literal caller, Literal prepared, Statement statement) {
			this.caller = caller;
			this.prepared = prepared;
			this.statement = statement;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			if (object != null) {
				assertThat(object).isEqualTo(prepared);
			}
			return new CloseableIteratorIteration<>(List.of(statement).iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}

		@Override
		public Function<Value, Value> getValuePreparer() {
			return value -> caller.equals(value) ? prepared : value;
		}
	}
}
